    testPostgresRegexPattern(postgresCatalog, "test_db", "test_db\\..*\\..*", Arrays.asList("test_db.public.test_table1", "test_db.public.test_table2", "test_db.test_schema.data_table1", "test_db.test_schema.data_table2"));
    testPostgresRegexPattern(postgresCatalog, ".*", ".*\\..*\\.nonexistent.*", Collections.emptyList());
}

