@Test
public void testGenerateMergeSql() throws Exception {
    // Create a mock DatabendSinkWriter
    DatabendSinkWriter sinkWriter = mock(DatabendSinkWriter.class);
    // Set up the real method to test
    when(sinkWriter.generateMergeSql()).thenCallRealMethod();
    // Use reflection to set private fields
    setPrivateField(sinkWriter, "conflictKey", "id");
    setPrivateField(sinkWriter, "sinkTablePath", TablePath.of("test_db", "target_table"));
    setPrivateField(sinkWriter, "streamName", "cdc_stream");
    setPrivateField(sinkWriter, "enableDelete", true);
    setPrivateField(sinkWriter, "targetTableName", "target_table");
    // Mock catalogTable
    org.apache.seatunnel.api.table.catalog.CatalogTable catalogTable = mock(org.apache.seatunnel.api.table.catalog.CatalogTable.class);
    SeaTunnelRowType rowType = new SeaTunnelRowType(new String[] { "id", "name", "score" }, new org.apache.seatunnel.api.table.type.SeaTunnelDataType[] { BasicType.INT_TYPE, BasicType.STRING_TYPE, BasicType.DOUBLE_TYPE });
    when(catalogTable.getSeaTunnelRowType()).thenReturn(rowType);
    setPrivateField(sinkWriter, "catalogTable", catalogTable);
    // Call the method
    String mergeSql = sinkWriter.generateMergeSql();
    // Expected SQL
    String expectedSql = "MERGE INTO test_db.target_table a " + "USING (SELECT raw_data:id as id, raw_data:name as name, raw_data:score as score, action " + "FROM test_db.cdc_stream " + "QUALIFY ROW_NUMBER() OVER(PARTITION BY id ORDER BY add_time DESC) = 1) b " + "ON a.id = b.id " + "WHEN MATCHED AND b.action = 'update' THEN UPDATE * " + "WHEN MATCHED AND b.action = 'delete' THEN DELETE " + "WHEN NOT MATCHED AND b.action!='delete' THEN INSERT *";
    assertEquals(expectedSql, mergeSql);
}

